    char *bind_addr = NULL;
    char *tmate_host = NULL;
    char *keys_dir = NULL;
    int ssh_port = 0;
    int ssh_port_advertized = 0;
    char *websocket_hostname = NULL;
    int websocket_port = 0;
    bool use_proxy_protocol = false;
    int log_level = 0;

    while ((opt = getopt(argc, argv, "b:h:k:p:q:w:z:xv")) != -1) {
        switch (opt) {
            case 'b':
                if (strlen(optarg) > 255) {
                    fprintf(stderr, "Error: bind_addr too long\n");
                    return 1;
                }
                bind_addr = xstrdup(optarg);
                break;
            case 'h':
                if (strlen(optarg) > 255) {
                    fprintf(stderr, "Error: tmate_host too long\n");
                    return 1;
                }
                tmate_host = xstrdup(optarg);
                break;
            case 'k':
                if (strlen(optarg) > 255) {
                    fprintf(stderr, "Error: keys_dir too long\n");
                    return 1;
                }
                keys_dir = xstrdup(optarg);
                break;
            case 'p':
                ssh_port = atoi(optarg);
                if (ssh_port <= 0 || ssh_port > 65535) {
                    fprintf(stderr, "Error: invalid ssh_port\n");
                    return 1;
                }
                break;
            case 'q':
                ssh_port_advertized = atoi(optarg);
                if (ssh_port_advertized <= 0 || ssh_port_advertized > 65535) {
                    fprintf(stderr, "Error: invalid ssh_port_advertized\n");
                    return 1;
                }
                break;
            case 'w':
                if (strlen(optarg) > 255) {
                    fprintf(stderr, "Error: websocket_hostname too long\n");
                    return 1;
                }
                websocket_hostname = xstrdup(optarg);
                break;
            case 'z':
                websocket_port = atoi(optarg);
                if (websocket_port <= 0 || websocket_port > 65535) {
                    fprintf(stderr, "Error: invalid websocket_port\n");
                    return 1;
                }
                break;
            case 'x':
                use_proxy_protocol = true;
                break;
            case 'v':
                log_level++;
                break;
            default:
                usage();
                return 1;
        }
    }

    init_logging(log_level);

    setup_locale();

    if (!tmate_host) {
        tmate_host = get_full_hostname();
    }

    cmdline = *argv;
    cmdline_end = *envp;

    tmate_preload_trace_lib();
    tmate_catch_sigsegv();
    tmate_init_rand();

    if (mkdir(TMATE_WORKDIR, 0701) < 0 && errno != EEXIST) {
        tmate_fatal("Cannot prepare session in " TMATE_WORKDIR);
    }

    /* The websocket server needs to access the /session dir to rename sockets */
    if (chmod(TMATE_WORKDIR, 0701) < 0 || chmod(TMATE_WORKDIR "/sessions", 0703) < 0 || chmod(TMATE_WORKDIR "/jail", 0700) < 0) {
        tmate_fatal("Cannot prepare session in " TMATE_WORKDIR);
    }

    tmate_ssh_server_main(tmate_session, keys_dir, bind_addr, ssh_port);
    free(bind_addr);
    free(tmate_host);
    free(keys_dir);
    free(websocket_hostname);
    return 0;
}
```

By adding these improvements, the function becomes more secure and robust against potential security vulnerabilities.

