    if (krb5rc == KRB5_KT_NOTFOUND) {
        rc = 1;
        fprintf(stderr, "Keytab entry not found for principal: %s\n", krb5_get_error_message(krb5context, krb5rc));
        goto exit;
    } else if (krb5rc) {
        fprintf(stderr, "Failed to retrieve keytab entry: %s\n", krb5_get_error_message(krb5context, krb5rc));
        goto exit;
    }

    // Free resources
    krb5_kt_free_entry(krb5context, &entry);
    krb5_free_principal(krb5context, princ);
    krb5_kt_close(krb5context, krb5keytab);
    krb5_free_context(krb5context);

    return rc;

exit:
    if (krb5keytab) krb5_kt_close(krb5context, krb5keytab);
    if (princ) krb5_free_principal(krb5context, princ);
    if (krb5context) krb5_free_context(krb5context);
